INSERT INTO `shop_config` (`content`,`config_key`) VALUES ('{"brands":["赫洛嘉"],"shopName":"赫洛嘉","categories":["精华水","乳液","面霜","精华油"],"withdrawFee":200,"serviceHours":"","servicePhone":"","agreementText":"赫洛嘉商城用户协议与隐私说明\\n更新日期：2026年9月20日\\n\\n一、适用范围与联系渠道\\n本说明适用于赫洛嘉商城提供的商品浏览、购物、售后、企业采购、专属拿货及分销推广服务。经营主体信息请在微信小程序右上角菜单内查看小程序主体资料。如对本说明、个人信息处理或订单有疑问，可通过商城“我的—在线客服”联系商家；协议页面也提供客服入口。\\n\\n二、账号与服务使用\\n你可以先浏览商品；下单及查看个人业务需要登录。微信登录时，我们使用微信提供的登录凭证及账号标识建立、识别商城会员，不会因此自动取得你的微信昵称、头像、手机号或聊天记录。你主动填写的昵称、头像、联系手机号用于资料展示和服务联系。请妥善保管账号，仅提交真实、合法且有权使用的信息。企业采购和分销资格以审核结果及当前页面规则为准。\\n\\n三、购物、履约与售后信息\\n下单时，我们处理所选商品、数量、价格、收货人姓名、联系电话、收货地址、订单备注及订单状态，用于计价、配送、通知和售后。你主动提交的退换货原因、说明、图片及退货物流信息用于处理售后。微信支付由微信支付服务提供方处理；商城处理订单号、金额、支付结果及交易标识，以核对付款和退款，不收集你的微信支付密码或银行卡支付密码。是否付款以支付结果和订单核实状态为准，请勿仅凭页面跳转判断。\\n\\n四、企业采购与推广业务\\n申请企业认证时，企业类型、企业名称、统一社会信用代码、营业执照、联系人及电话用于核验企业资格、联系申请人和提供采购服务。按你使用的功能，还会处理企业成员、授权角色、采购审批、发票资料、付款凭证和账期记录。请仅上传办理业务必要的资料，遮挡无关个人信息。\\n申请及使用分销、专属拿货服务时，我们处理申请资料、邀请来源、推广关联、有效订单金额、积分优惠、佣金及结算记录，用于资格审核、权益计算和对账。分享链接会携带你的推广编号以识别推广来源；该编号不是登录密码。助手邀请码用于建立受限的业务查看关系，请仅交给你授权的人，主账号可以解除关联。助手只能查看系统授权的业务摘要，不能因此代你付款或提现。\\n\\n五、客服、评价与公开内容\\n你主动发送的客服消息、图片及相关订单信息用于回复咨询和处理纠纷。发布商品评价、图片和展示昵称头像时，相应展示内容可能被其他访问者看到，请避免包含电话、住址、证件或无关人员资料。客服材料和企业认证材料不作为商品评价公开展示。不要上传他人未经授权的敏感资料。\\n\\n六、设备能力与本地存储\\n在你主动选择上传头像、资质、凭证、评价或客服图片时，客户端可能调用相机、相册或文件选择能力；仅处理你选定并提交的文件。企业批量采购导入只读取你选择的文件，不读取全部微信聊天内容。保存推广图片时可能需要相册保存权限，你可以拒绝或在微信及系统设置中管理相关权限；拒绝后仅对应上传、保存等功能受影响。\\n复制邀请码、订单号或分享链接时，客户端按你的操作写入剪贴板，不主动在后台读取剪贴板内容。商城使用本地存储保存登录状态、购物清单和部分业务草稿或待核实订单记录；退出登录不代表所有本地业务记录均被删除，如需清理，可结合微信的小程序缓存管理操作。\\n本商城当前不为购物要求读取通讯录或持续获取精确定位；收货地区和地址由你填写。服务端还会产生请求、登录、操作及安全日志，用于故障排查、账号保护和交易核对。\\n\\n七、信息使用与必要共享\\n信息用于上述与你选择的服务直接相关的目的。履约所需的收货资料会提供给实际承接订单的配送服务方；支付相关必要信息由微信支付处理；小程序登录及相应平台能力由微信提供。企业内授权成员、经你授权的助手只能在所获业务权限内查看相应资料。上述参与方按实际业务所需处理信息，不代表他们可使用你的完整账号资料。\\n我们不以出售个人信息作为商城服务内容。因法律规定、争议处理或依法有权机关要求而提供信息时，以必要范围为限。新增处理目的、信息类型或接收方需要重新告知、取得同意时，将按适用要求另行处理。\\n\\n八、保存与安全\\n信息保存在用于商城业务的服务系统和必要的本地缓存中。我们根据服务所需及适用的交易记录、财务和争议处理保存要求保存相关资料；不能承诺退出登录或取消订单后立即删除所有记录。超出必要保存期限后，应按适用要求删除或匿名化。商城采用账号校验、权限控制等措施限制访问，支付凭据不放入小程序公开安装包。互联网环境不存在绝对安全，请勿向他人提供登录凭据或无关敏感信息。\\n\\n九、查询、更正、删除及注销\\n你可以通过个人资料、地址管理、订单和相应业务页面查看、修改支持自助管理的信息。申请查询复制、删除信息、撤回同意、注销账号，或对处理方式提出异议，请通过商城在线客服提出。为保护账号和订单安全，处理前可能核验身份；请不要在公开评价中提交此类请求。依法必须保留的交易记录、尚未完成的订单或争议可能影响立即删除的范围，商家应说明原因及后续处理方式。撤回同意不影响撤回前已依法进行的处理，也可能使依赖相关信息的功能无法继续提供。\\n\\n十、商品与交易约定\\n商品规格、价格、优惠、运费、预计履约方式和售后说明以你确认订单时展示的内容及适用法律为准。请核对收货信息和实付金额；遇到缺货、异常付款或物流问题可联系客服。不得通过虚假订单、冒用身份或篡改信息获取权益。页面说明不排除消费者依法享有的退换货、知情及其他权利；如与强制性法律规定冲突，以法律规定为准。\\n\\n十一、未成年人及更新\\n未成年人请在监护人指导下使用涉及个人信息和支付的服务；不满十四周岁用户涉及个人信息处理时，应由监护人联系商家并按适用要求办理。若发现未经监护人适当授权提交的未成年人信息，可联系客服核实处理。\\n当功能或信息处理方式变化时，本说明会相应更新。涉及重要变化及需要重新取得同意的事项，将另行告知。本页面说明与微信平台展示的隐私保护指引应按实际功能保持一致。","serviceNotice":"","couponDiscount":0,"couponThreshold":0,"withdrawMinimum":10000,"minimumWholesale":300000,"commissionPercent":10,"withdrawWorkingDays":3,"walletPaymentEnabled":true,"commissionAfterReceipt":true,"simulationPaymentEnabled":false,"shareBaseUrl":"https://shop.example.com"}','rules');
